<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>So sánh sản phẩm</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-950 p-5 text-slate-100"><main class="mx-auto max-w-6xl"><a href="?page=products" class="text-blue-300">← Chọn sản phẩm khác</a><h1 class="my-5 text-3xl font-bold">So sánh sản phẩm</h1><?php if(count($products)<2): ?><p>Chọn ít nhất hai sản phẩm để so sánh.</p><?php else: ?><div class="overflow-auto rounded-xl bg-slate-900"><table class="w-full text-left"><thead><tr><th class="p-4">Thông số</th><?php foreach($products as $p): ?><th class="p-4"><?= $e($p['name']) ?></th><?php endforeach ?></tr></thead><tbody><?php foreach(['Hãng'=>'brand','Danh mục'=>'category','Giá thấp nhất'=>'price','Giá niêm yết'=>'compare_price','Tồn kho'=>'stock','Cấu hình phiên bản'=>'attributes'] as $label=>$key): ?><tr class="border-t border-slate-700"><th class="p-4"><?= $e($label) ?></th><?php foreach($products as $p): ?><td class="p-4"><?= $key==='price'||$key==='compare_price'?number_format((float)$p[$key],0,',','.').' ₫':$e($p[$key]??'—') ?></td><?php endforeach ?></tr><?php endforeach ?></tbody></table></div><?php endif ?></main></body></html>
